      "NfseManifestationRequest": {
        "type": "object",
        "properties": {
          "ambiente": {
            "type": [
              "integer",
              "string"
            ],
            "enum": [
              1,
              2,
              "1",
              "2"
            ]
          },
          "chave": {
            "type": "string",
            "minLength": 50,
            "maxLength": 50,
            "description": "Nacional NFSe access key, exactly 50 characters; a UUID is not accepted."
          },
          "manifestador": {
            "type": [
              "integer",
              "string"
            ],
            "enum": [
              1,
              2,
              "1",
              "2"
            ]
          },
          "evento": {
            "type": [
              "integer",
              "string"
            ],
            "enum": [
              1,
              2,
              "1",
              "2"
            ]
          },
          "motivo_rejeicao": {
            "type": [
              "integer",
              "string"
            ],
            "enum": [
              1,
              2,
              3,
              4,
              5,
              9,
              "1",
              "2",
              "3",
              "4",
              "5",
              "9"
            ]
          },
          "justificativa_rejeicao": {
            "type": "string",
            "minLength": 15,
            "maxLength": 255
          }
        },
        "additionalProperties": true,
        "required": [
          "ambiente",
          "chave",
          "manifestador",
          "evento"
        ],
        "description": "Padrão Nacional only, valid certificate required. manifestador 1 tomador / 2 intermediary; evento 1 confirmation / 2 rejection. Rejection requires motivo_rejeicao; reason 9 other requires justification. This creates a fiscal event and is excluded from read-only validation.",
        "allOf": [
          {
            "if": {
              "properties": {
                "evento": {
                  "enum": [
                    2,
                    "2"
                  ]
                }
              },
              "required": [
                "evento"
              ]
            },
            "then": {
              "required": [
                "motivo_rejeicao"
              ]
            }
          },
          {
            "if": {
              "properties": {
                "motivo_rejeicao": {
                  "enum": [
                    9,
                    "9"
                  ]
                }
              },
              "required": [
                "motivo_rejeicao"
              ]
            },
            "then": {
              "required": [
                "justificativa_rejeicao"
              ]
            }
          }
        ]
      },
